macro_rules! deps {
    () => {
        Attributes!();
        Record!();
        Current!();
        Metadata!();
        Dispatch!();
        LevelFilter!();
        Visit!();
        Event!();
        WeakDispatch!();
        Interest!();
        Id!();
    };
}

macro_rules! Subscriber {
    () => {
        deps!();
        # [doc = " Trait representing the functions required to collect trace data."] # [doc = ""] # [doc = " Crates that provide implementations of methods for collecting or recording"] # [doc = " trace data should implement the `Subscriber` interface. This trait is"] # [doc = " intended to represent fundamental primitives for collecting trace events and"] # [doc = " spans — other libraries may offer utility functions and types to make"] # [doc = " subscriber implementations more modular or improve the ergonomics of writing"] # [doc = " subscribers."] # [doc = ""] # [doc = " A subscriber is responsible for the following:"] # [doc = " - Registering new spans as they are created, and providing them with span"] # [doc = "   IDs. Implicitly, this means the subscriber may determine the strategy for"] # [doc = "   determining span equality."] # [doc = " - Recording the attachment of field values and follows-from annotations to"] # [doc = "   spans."] # [doc = " - Filtering spans and events, and determining when those filters must be"] # [doc = "   invalidated."] # [doc = " - Observing spans as they are entered, exited, and closed, and events as"] # [doc = "   they occur."] # [doc = ""] # [doc = " When a span is entered or exited, the subscriber is provided only with the"] # [doc = " [ID] with which it tagged that span when it was created. This means"] # [doc = " that it is up to the subscriber to determine whether and how span _data_ —"] # [doc = " the fields and metadata describing the span — should be stored. The"] # [doc = " [`new_span`] function is called when a new span is created, and at that"] # [doc = " point, the subscriber _may_ choose to store the associated data if it will"] # [doc = " be referenced again. However, if the data has already been recorded and will"] # [doc = " not be needed by the implementations of `enter` and `exit`, the subscriber"] # [doc = " may freely discard that data without allocating space to store it."] # [doc = ""] # [doc = " ## Overriding default impls"] # [doc = ""] # [doc = " Some trait methods on `Subscriber` have default implementations, either in"] # [doc = " order to reduce the surface area of implementing `Subscriber`, or for"] # [doc = " backward-compatibility reasons. However, many subscribers will likely want"] # [doc = " to override these default implementations."] # [doc = ""] # [doc = " The following methods are likely of interest:"] # [doc = ""] # [doc = " - [`register_callsite`] is called once for each callsite from which a span"] # [doc = "   event may originate, and returns an [`Interest`] value describing whether or"] # [doc = "   not the subscriber wishes to see events or spans from that callsite. By"] # [doc = "   default, it calls [`enabled`], and returns `Interest::always()` if"] # [doc = "   `enabled` returns true, or `Interest::never()` if enabled returns false."] # [doc = "   However, if the subscriber's interest can change dynamically at runtime,"] # [doc = "   it may want to override this function to return `Interest::sometimes()`."] # [doc = "   Additionally, subscribers which wish to perform a behaviour once for each"] # [doc = "   callsite, such as allocating storage for data related to that callsite,"] # [doc = "   can perform it in `register_callsite`."] # [doc = ""] # [doc = "   See also the [documentation on the callsite registry][cs-reg] for details"] # [doc = "   on [`register_callsite`]."] # [doc = ""] # [doc = " - [`event_enabled`] is called once before every call to the [`event`]"] # [doc = "   method. This can be used to implement filtering on events once their field"] # [doc = "   values are known, but before any processing is done in the `event` method."] # [doc = " - [`clone_span`] is called every time a span ID is cloned, and [`try_close`]"] # [doc = "   is called when a span ID is dropped. By default, these functions do"] # [doc = "   nothing. However, they can be used to implement reference counting for"] # [doc = "   spans, allowing subscribers to free storage for span data and to determine"] # [doc = "   when a span has _closed_ permanently (rather than being exited)."] # [doc = "   Subscribers which store per-span data or which need to track span closures"] # [doc = "   should override these functions together."] # [doc = ""] # [doc = " [ID]: super::span::Id"] # [doc = " [`new_span`]: Subscriber::new_span"] # [doc = " [`register_callsite`]: Subscriber::register_callsite"] # [doc = " [`enabled`]: Subscriber::enabled"] # [doc = " [`clone_span`]: Subscriber::clone_span"] # [doc = " [`try_close`]: Subscriber::try_close"] # [doc = " [cs-reg]: crate::callsite#registering-callsites"] # [doc = " [`event`]: Subscriber::event"] # [doc = " [`event_enabled`]: Subscriber::event_enabled"] pub trait Subscriber : 'static { # [doc = " Invoked when this subscriber becomes a [`Dispatch`]."] # [doc = ""] # [doc = " ## Avoiding Memory Leaks"] # [doc = ""] # [doc = " `Subscriber`s should not store their own [`Dispatch`]. Because the"] # [doc = " `Dispatch` owns the `Subscriber`, storing the `Dispatch` within the"] # [doc = " `Subscriber` will create a reference count cycle, preventing the `Dispatch`"] # [doc = " from ever being dropped."] # [doc = ""] # [doc = " Instead, when it is necessary to store a cyclical reference to the"] # [doc = " `Dispatch` within a `Subscriber`, use [`Dispatch::downgrade`] to convert a"] # [doc = " `Dispatch` into a [`WeakDispatch`]. This type is analogous to"] # [doc = " [`std::sync::Weak`], and does not create a reference count cycle. A"] # [doc = " [`WeakDispatch`] can be stored within a `Subscriber` without causing a"] # [doc = " memory leak, and can be [upgraded] into a `Dispatch` temporarily when"] # [doc = " the `Dispatch` must be accessed by the `Subscriber`."] # [doc = ""] # [doc = " [`WeakDispatch`]: crate::dispatcher::WeakDispatch"] # [doc = " [upgraded]: crate::dispatcher::WeakDispatch::upgrade"] fn on_register_dispatch (& self , subscriber : & Dispatch) { let _ = subscriber ; } # [doc = " Registers a new [callsite] with this subscriber, returning whether or not"] # [doc = " the subscriber is interested in being notified about the callsite."] # [doc = ""] # [doc = " By default, this function assumes that the subscriber's [filter]"] # [doc = " represents an unchanging view of its interest in the callsite. However,"] # [doc = " if this is not the case, subscribers may override this function to"] # [doc = " indicate different interests, or to implement behaviour that should run"] # [doc = " once for every callsite."] # [doc = ""] # [doc = " This function is guaranteed to be called at least once per callsite on"] # [doc = " every active subscriber. The subscriber may store the keys to fields it"] # [doc = " cares about in order to reduce the cost of accessing fields by name,"] # [doc = " preallocate storage for that callsite, or perform any other actions it"] # [doc = " wishes to perform once for each callsite."] # [doc = ""] # [doc = " The subscriber should then return an [`Interest`], indicating"] # [doc = " whether it is interested in being notified about that callsite in the"] # [doc = " future. This may be `Always` indicating that the subscriber always"] # [doc = " wishes to be notified about the callsite, and its filter need not be"] # [doc = " re-evaluated; `Sometimes`, indicating that the subscriber may sometimes"] # [doc = " care about the callsite but not always (such as when sampling), or"] # [doc = " `Never`, indicating that the subscriber never wishes to be notified about"] # [doc = " that callsite. If all active subscribers return `Never`, a callsite will"] # [doc = " never be enabled unless a new subscriber expresses interest in it."] # [doc = ""] # [doc = " `Subscriber`s which require their filters to be run every time an event"] # [doc = " occurs or a span is entered/exited should return `Interest::sometimes`."] # [doc = " If a subscriber returns `Interest::sometimes`, then its [`enabled`] method"] # [doc = " will be called every time an event or span is created from that callsite."] # [doc = ""] # [doc = " For example, suppose a sampling subscriber is implemented by"] # [doc = " incrementing a counter every time `enabled` is called and only returning"] # [doc = " `true` when the counter is divisible by a specified sampling rate. If"] # [doc = " that subscriber returns `Interest::always` from `register_callsite`, then"] # [doc = " the filter will not be re-evaluated once it has been applied to a given"] # [doc = " set of metadata. Thus, the counter will not be incremented, and the span"] # [doc = " or event that corresponds to the metadata will never be `enabled`."] # [doc = ""] # [doc = " `Subscriber`s that need to change their filters occasionally should call"] # [doc = " [`rebuild_interest_cache`] to re-evaluate `register_callsite` for all"] # [doc = " callsites."] # [doc = ""] # [doc = " Similarly, if a `Subscriber` has a filtering strategy that can be"] # [doc = " changed dynamically at runtime, it would need to re-evaluate that filter"] # [doc = " if the cached results have changed."] # [doc = ""] # [doc = " A subscriber which manages fanout to multiple other subscribers"] # [doc = " should proxy this decision to all of its child subscribers,"] # [doc = " returning `Interest::never` only if _all_ such children return"] # [doc = " `Interest::never`. If the set of subscribers to which spans are"] # [doc = " broadcast may change dynamically, the subscriber should also never"] # [doc = " return `Interest::Never`, as a new subscriber may be added that _is_"] # [doc = " interested."] # [doc = ""] # [doc = " See the [documentation on the callsite registry][cs-reg] for more"] # [doc = " details on how and when the `register_callsite` method is called."] # [doc = ""] # [doc = " # Notes"] # [doc = " This function may be called again when a new subscriber is created or"] # [doc = " when the registry is invalidated."] # [doc = ""] # [doc = " If a subscriber returns `Interest::never` for a particular callsite, it"] # [doc = " _may_ still see spans and events originating from that callsite, if"] # [doc = " another subscriber expressed interest in it."] # [doc = ""] # [doc = " [callsite]: crate::callsite"] # [doc = " [filter]: Self::enabled"] # [doc = " [metadata]: super::metadata::Metadata"] # [doc = " [`enabled`]: Subscriber::enabled()"] # [doc = " [`rebuild_interest_cache`]: super::callsite::rebuild_interest_cache"] # [doc = " [cs-reg]: crate::callsite#registering-callsites"] fn register_callsite (& self , metadata : & 'static Metadata < 'static >) -> Interest { if self . enabled (metadata) { Interest :: always () } else { Interest :: never () } } # [doc = " Returns true if a span or event with the specified [metadata] would be"] # [doc = " recorded."] # [doc = ""] # [doc = " By default, it is assumed that this filter needs only be evaluated once"] # [doc = " for each callsite, so it is called by [`register_callsite`] when each"] # [doc = " callsite is registered. The result is used to determine if the subscriber"] # [doc = " is always [interested] or never interested in that callsite. This is intended"] # [doc = " primarily as an optimization, so that expensive filters (such as those"] # [doc = " involving string search, et cetera) need not be re-evaluated."] # [doc = ""] # [doc = " However, if the subscriber's interest in a particular span or event may"] # [doc = " change, or depends on contexts only determined dynamically at runtime,"] # [doc = " then the `register_callsite` method should be overridden to return"] # [doc = " [`Interest::sometimes`]. In that case, this function will be called every"] # [doc = " time that span or event occurs."] # [doc = ""] # [doc = " [metadata]: super::metadata::Metadata"] # [doc = " [interested]: Interest"] # [doc = " [`Interest::sometimes`]: Interest::sometimes"] # [doc = " [`register_callsite`]: Subscriber::register_callsite()"] fn enabled (& self , metadata : & Metadata < '_ >) -> bool ; # [doc = " Returns the highest [verbosity level][level] that this `Subscriber` will"] # [doc = " enable, or `None`, if the subscriber does not implement level-based"] # [doc = " filtering or chooses not to implement this method."] # [doc = ""] # [doc = " If this method returns a [`Level`][level], it will be used as a hint to"] # [doc = " determine the most verbose level that will be enabled. This will allow"] # [doc = " spans and events which are more verbose than that level to be skipped"] # [doc = " more efficiently. Subscribers which perform filtering are strongly"] # [doc = " encouraged to provide an implementation of this method."] # [doc = ""] # [doc = " If the maximum level the subscriber will enable can change over the"] # [doc = " course of its lifetime, it is free to return a different value from"] # [doc = " multiple invocations of this method. However, note that changes in the"] # [doc = " maximum level will **only** be reflected after the callsite [`Interest`]"] # [doc = " cache is rebuilt, by calling the [`callsite::rebuild_interest_cache`][rebuild]"] # [doc = " function. Therefore, if the subscriber will change the value returned by"] # [doc = " this method, it is responsible for ensuring that"] # [doc = " [`rebuild_interest_cache`][rebuild] is called after the value of the max"] # [doc = " level changes."] # [doc = ""] # [doc = " [level]: super::Level"] # [doc = " [rebuild]: super::callsite::rebuild_interest_cache"] fn max_level_hint (& self) -> Option < LevelFilter > { None } # [doc = " Visit the construction of a new span, returning a new [span ID] for the"] # [doc = " span being constructed."] # [doc = ""] # [doc = " The provided [`Attributes`] contains any field values that were provided"] # [doc = " when the span was created. The subscriber may pass a [visitor] to the"] # [doc = " `Attributes`' [`record` method] to record these values."] # [doc = ""] # [doc = " IDs are used to uniquely identify spans and events within the context of a"] # [doc = " subscriber, so span equality will be based on the returned ID. Thus, if"] # [doc = " the subscriber wishes for all spans with the same metadata to be"] # [doc = " considered equal, it should return the same ID every time it is given a"] # [doc = " particular set of metadata. Similarly, if it wishes for two separate"] # [doc = " instances of a span with the same metadata to *not* be equal, it should"] # [doc = " return a distinct ID every time this function is called, regardless of"] # [doc = " the metadata."] # [doc = ""] # [doc = " Note that the subscriber is free to assign span IDs based on whatever"] # [doc = " scheme it sees fit. Any guarantees about uniqueness, ordering, or ID"] # [doc = " reuse are left up to the subscriber implementation to determine."] # [doc = ""] # [doc = " [span ID]: super::span::Id"] # [doc = " [`Attributes`]: super::span::Attributes"] # [doc = " [visitor]: super::field::Visit"] # [doc = " [`record` method]: super::span::Attributes::record"] fn new_span (& self , span : & span :: Attributes < '_ >) -> span :: Id ; # [doc = " Record a set of values on a span."] # [doc = ""] # [doc = " This method will be invoked when value is recorded on a span."] # [doc = " Recording multiple values for the same field is possible,"] # [doc = " but the actual behaviour is defined by the subscriber implementation."] # [doc = ""] # [doc = " Keep in mind that a span might not provide a value"] # [doc = " for each field it declares."] # [doc = ""] # [doc = " The subscriber is expected to provide a [visitor] to the `Record`'s"] # [doc = " [`record` method] in order to record the added values."] # [doc = ""] # [doc = " # Example"] # [doc = "  \"foo = 3\" will be recorded when [`record`] is called on the"] # [doc = " `Attributes` passed to `new_span`."] # [doc = " Since values are not provided for the `bar` and `baz` fields,"] # [doc = " the span's `Metadata` will indicate that it _has_ those fields,"] # [doc = " but values for them won't be recorded at this time."] # [doc = ""] # [doc = " ```rust,ignore"] # [doc = " # use tracing::span;"] # [doc = ""] # [doc = " let mut span = span!(\"my_span\", foo = 3, bar, baz);"] # [doc = ""] # [doc = " // `Subscriber::record` will be called with a `Record`"] # [doc = " // containing \"bar = false\""] # [doc = " span.record(\"bar\", &false);"] # [doc = ""] # [doc = " // `Subscriber::record` will be called with a `Record`"] # [doc = " // containing \"baz = \"a string\"\""] # [doc = " span.record(\"baz\", &\"a string\");"] # [doc = " ```"] # [doc = ""] # [doc = " [visitor]: super::field::Visit"] # [doc = " [`record`]: super::span::Attributes::record"] # [doc = " [`record` method]: super::span::Record::record"] fn record (& self , span : & span :: Id , values : & span :: Record < '_ >) ; # [doc = " Adds an indication that `span` follows from the span with the id"] # [doc = " `follows`."] # [doc = ""] # [doc = " This relationship differs somewhat from the parent-child relationship: a"] # [doc = " span may have any number of prior spans, rather than a single one; and"] # [doc = " spans are not considered to be executing _inside_ of the spans they"] # [doc = " follow from. This means that a span may close even if subsequent spans"] # [doc = " that follow from it are still open, and time spent inside of a"] # [doc = " subsequent span should not be included in the time its precedents were"] # [doc = " executing. This is used to model causal relationships such as when a"] # [doc = " single future spawns several related background tasks, et cetera."] # [doc = ""] # [doc = " If the subscriber has spans corresponding to the given IDs, it should"] # [doc = " record this relationship in whatever way it deems necessary. Otherwise,"] # [doc = " if one or both of the given span IDs do not correspond to spans that the"] # [doc = " subscriber knows about, or if a cyclical relationship would be created"] # [doc = " (i.e., some span _a_ which proceeds some other span _b_ may not also"] # [doc = " follow from _b_), it may silently do nothing."] fn record_follows_from (& self , span : & span :: Id , follows : & span :: Id) ; # [doc = " Determine if an [`Event`] should be recorded."] # [doc = ""] # [doc = " By default, this returns `true` and `Subscriber`s can filter events in"] # [doc = " [`event`][Self::event] without any penalty. However, when `event` is"] # [doc = " more complicated, this can be used to determine if `event` should be"] # [doc = " called at all, separating out the decision from the processing."] fn event_enabled (& self , event : & Event < '_ >) -> bool { let _ = event ; true } # [doc = " Records that an [`Event`] has occurred."] # [doc = ""] # [doc = " This method will be invoked when an Event is constructed by"] # [doc = " the `Event`'s [`dispatch` method]. For example, this happens internally"] # [doc = " when an event macro from `tracing` is called."] # [doc = ""] # [doc = " The key difference between this method and `record` is that `record` is"] # [doc = " called when a value is recorded for a field defined by a span,"] # [doc = " while `event` is called when a new event occurs."] # [doc = ""] # [doc = " The provided `Event` struct contains any field values attached to the"] # [doc = " event. The subscriber may pass a [visitor] to the `Event`'s"] # [doc = " [`record` method] to record these values."] # [doc = ""] # [doc = " [`Event`]: super::event::Event"] # [doc = " [visitor]: super::field::Visit"] # [doc = " [`record` method]: super::event::Event::record"] # [doc = " [`dispatch` method]: super::event::Event::dispatch"] fn event (& self , event : & Event < '_ >) ; # [doc = " Records that a span has been entered."] # [doc = ""] # [doc = " When entering a span, this method is called to notify the subscriber"] # [doc = " that the span has been entered. The subscriber is provided with the"] # [doc = " [span ID] of the entered span, and should update any internal state"] # [doc = " tracking the current span accordingly."] # [doc = ""] # [doc = " [span ID]: super::span::Id"] fn enter (& self , span : & span :: Id) ; # [doc = " Records that a span has been exited."] # [doc = ""] # [doc = " When exiting a span, this method is called to notify the subscriber"] # [doc = " that the span has been exited. The subscriber is provided with the"] # [doc = " [span ID] of the exited span, and should update any internal state"] # [doc = " tracking the current span accordingly."] # [doc = ""] # [doc = " Exiting a span does not imply that the span will not be re-entered."] # [doc = ""] # [doc = " [span ID]: super::span::Id"] fn exit (& self , span : & span :: Id) ; # [doc = " Notifies the subscriber that a [span ID] has been cloned."] # [doc = ""] # [doc = " This function is guaranteed to only be called with span IDs that were"] # [doc = " returned by this subscriber's `new_span` function."] # [doc = ""] # [doc = " Note that the default implementation of this function this is just the"] # [doc = " identity function, passing through the identifier. However, it can be"] # [doc = " used in conjunction with [`try_close`] to track the number of handles"] # [doc = " capable of `enter`ing a span. When all the handles have been dropped"] # [doc = " (i.e., `try_close` has been called one more time than `clone_span` for a"] # [doc = " given ID), the subscriber may assume that the span will not be entered"] # [doc = " again. It is then free to deallocate storage for data associated with"] # [doc = " that span, write data from that span to IO, and so on."] # [doc = ""] # [doc = " For more unsafe situations, however, if `id` is itself a pointer of some"] # [doc = " kind this can be used as a hook to \"clone\" the pointer, depending on"] # [doc = " what that means for the specified pointer."] # [doc = ""] # [doc = " [span ID]: super::span::Id"] # [doc = " [`try_close`]: Subscriber::try_close"] fn clone_span (& self , id : & span :: Id) -> span :: Id { id . clone () } # [doc = " **This method is deprecated.**"] # [doc = ""] # [doc = " Using `drop_span` may result in subscribers composed using"] # [doc = " `tracing-subscriber` crate's `Layer` trait from observing close events."] # [doc = " Use [`try_close`] instead."] # [doc = ""] # [doc = " The default implementation of this function does nothing."] # [doc = ""] # [doc = " [`try_close`]: Subscriber::try_close"] # [deprecated (since = "0.1.2" , note = "use `Subscriber::try_close` instead")] fn drop_span (& self , _id : span :: Id) { } # [doc = " Notifies the subscriber that a [span ID] has been dropped, and returns"] # [doc = " `true` if there are now 0 IDs that refer to that span."] # [doc = ""] # [doc = " Higher-level libraries providing functionality for composing multiple"] # [doc = " subscriber implementations may use this return value to notify any"] # [doc = " \"layered\" subscribers that this subscriber considers the span closed."] # [doc = ""] # [doc = " The default implementation of this method calls the subscriber's"] # [doc = " [`drop_span`] method and returns `false`. This means that, unless the"] # [doc = " subscriber overrides the default implementation, close notifications"] # [doc = " will never be sent to any layered subscribers. In general, if the"] # [doc = " subscriber tracks reference counts, this method should be implemented,"] # [doc = " rather than `drop_span`."] # [doc = ""] # [doc = " This function is guaranteed to only be called with span IDs that were"] # [doc = " returned by this subscriber's `new_span` function."] # [doc = ""] # [doc = " It's guaranteed that if this function has been called once more than the"] # [doc = " number of times `clone_span` was called with the same `id`, then no more"] # [doc = " handles that can enter the span with that `id` exist. This means that it"] # [doc = " can be used in conjunction with [`clone_span`] to track the number of"] # [doc = " handles capable of `enter`ing a span. When all the handles have been"] # [doc = " dropped (i.e., `try_close` has been called one more time than"] # [doc = " `clone_span` for a given ID), the subscriber may assume that the span"] # [doc = " will not be entered again, and should return `true`. It is then free to"] # [doc = " deallocate storage for data associated with that span, write data from"] # [doc = " that span to IO, and so on."] # [doc = ""] # [doc = " **Note**: since this function is called when spans are dropped,"] # [doc = " implementations should ensure that they are unwind-safe. Panicking from"] # [doc = " inside of a `try_close` function may cause a double panic, if the span"] # [doc = " was dropped due to a thread unwinding."] # [doc = ""] # [doc = " [span ID]: super::span::Id"] # [doc = " [`clone_span`]: Subscriber::clone_span"] # [doc = " [`drop_span`]: Subscriber::drop_span"] fn try_close (& self , id : span :: Id) -> bool { # [allow (deprecated)] self . drop_span (id) ; false } # [doc = " Returns a type representing this subscriber's view of the current span."] # [doc = ""] # [doc = " If subscribers track a current span, they should override this function"] # [doc = " to return [`Current::new`] if the thread from which this method is"] # [doc = " called is inside a span, or [`Current::none`] if the thread is not"] # [doc = " inside a span."] # [doc = ""] # [doc = " By default, this returns a value indicating that the subscriber"] # [doc = " does **not** track what span is current. If the subscriber does not"] # [doc = " implement a current span, it should not override this method."] # [doc = ""] # [doc = " [`Current::new`]: super::span::Current#tymethod.new"] # [doc = " [`Current::none`]: super::span::Current#tymethod.none"] fn current_span (& self) -> span :: Current { span :: Current :: unknown () } # [doc = " If `self` is the same type as the provided `TypeId`, returns an untyped"] # [doc = " `*const` pointer to that type. Otherwise, returns `None`."] # [doc = ""] # [doc = " If you wish to downcast a `Subscriber`, it is strongly advised to use"] # [doc = " the safe API provided by [`downcast_ref`] instead."] # [doc = ""] # [doc = " This API is required for `downcast_raw` to be a trait method; a method"] # [doc = " signature like [`downcast_ref`] (with a generic type parameter) is not"] # [doc = " object-safe, and thus cannot be a trait method for `Subscriber`. This"] # [doc = " means that if we only exposed `downcast_ref`, `Subscriber`"] # [doc = " implementations could not override the downcasting behavior"] # [doc = ""] # [doc = " This method may be overridden by \"fan out\" or \"chained\" subscriber"] # [doc = " implementations which consist of multiple composed types. Such"] # [doc = " subscribers might allow `downcast_raw` by returning references to those"] # [doc = " component if they contain components with the given `TypeId`."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The [`downcast_ref`] method expects that the pointer returned by"] # [doc = " `downcast_raw` is non-null and points to a valid instance of the type"] # [doc = " with the provided `TypeId`. Failure to ensure this will result in"] # [doc = " undefined behaviour, so implementing `downcast_raw` is unsafe."] # [doc = ""] # [doc = " [`downcast_ref`]: #method.downcast_ref"] unsafe fn downcast_raw (& self , id : TypeId) -> Option < * const () > { if id == TypeId :: of :: < Self > () { Some (self as * const Self as * const ()) } else { None } } }
    };
}

Subscriber!()